"""Shared test helpers and fixtures."""

from dataclasses import dataclass
from typing import Optional

from google.adk.models.llm_request import LlmRequest
from google.adk.models.llm_response import LlmResponse
from google.genai import types


@dataclass
class FakeInspectResponse:
    is_safe: bool
    action: str = "Allow"
    severity: Optional[str] = None
    classifications: list = None
    rules: list = None
    event_id: Optional[str] = None

    def __post_init__(self):
        if self.classifications is None:
            self.classifications = []
        if self.rules is None:
            self.rules = []


@dataclass
class FakeRule:
    rule_name: str
    classification: Optional[str] = None


@dataclass
class FakeMCPInspectResponse:
    result: Optional[FakeInspectResponse] = None


def make_llm_request(text: str) -> LlmRequest:
    return LlmRequest(
        contents=[types.Content(role="user", parts=[types.Part(text=text)])],
    )


def make_llm_response(text: str) -> LlmResponse:
    return LlmResponse(
        content=types.Content(role="model", parts=[types.Part(text=text)])
    )

