"""Tests for _helpers.py text extraction utilities."""

import pytest
from unittest.mock import MagicMock

from google.genai import types

from aidefense_google_adk._helpers import (
    extract_all_user_text,
    extract_last_user_text,
    extract_model_text,
)


def _content(role: str, text: str) -> types.Content:
    return types.Content(role=role, parts=[types.Part(text=text)])


class TestExtractLastUserText:
    def test_single_user_message(self):
        contents = [_content("user", "Hello")]
        assert extract_last_user_text(contents) == "Hello"

    def test_returns_last_user_message(self):
        contents = [
            _content("user", "First"),
            _content("model", "Response"),
            _content("user", "Second"),
        ]
        assert extract_last_user_text(contents) == "Second"

    def test_no_user_messages(self):
        contents = [_content("model", "Only model")]
        assert extract_last_user_text(contents) is None

    def test_empty_contents(self):
        assert extract_last_user_text([]) is None

    def test_user_with_no_text_parts(self):
        content = types.Content(role="user", parts=[])
        assert extract_last_user_text([content]) is None

    def test_multipart_user_message(self):
        content = types.Content(
            role="user",
            parts=[types.Part(text="Part 1"), types.Part(text="Part 2")],
        )
        assert extract_last_user_text([content]) == "Part 1\nPart 2"

    def test_skips_none_text_parts(self):
        part_with_text = types.Part(text="Real text")
        part_no_text = types.Part(text=None)
        content = types.Content(role="user", parts=[part_no_text, part_with_text])
        assert extract_last_user_text([content]) == "Real text"


class TestExtractModelText:
    def test_basic_model_response(self):
        from google.adk.models.llm_response import LlmResponse

        resp = LlmResponse(
            content=types.Content(
                role="model", parts=[types.Part(text="Answer")]
            )
        )
        assert extract_model_text(resp) == "Answer"

    def test_none_content(self):
        from google.adk.models.llm_response import LlmResponse

        resp = LlmResponse(content=None)
        assert extract_model_text(resp) is None

    def test_empty_parts(self):
        from google.adk.models.llm_response import LlmResponse

        resp = LlmResponse(
            content=types.Content(role="model", parts=[])
        )
        assert extract_model_text(resp) is None

    def test_multipart_response(self):
        from google.adk.models.llm_response import LlmResponse

        resp = LlmResponse(
            content=types.Content(
                role="model",
                parts=[types.Part(text="A"), types.Part(text="B")],
            )
        )
        assert extract_model_text(resp) == "A\nB"


class TestExtractAllUserText:
    def test_collects_all_user_messages(self):
        contents = [
            _content("user", "First"),
            _content("model", "Response"),
            _content("user", "Second"),
        ]
        assert extract_all_user_text(contents) == "First\nSecond"

    def test_no_user_messages(self):
        contents = [_content("model", "Only model")]
        assert extract_all_user_text(contents) is None

    def test_empty(self):
        assert extract_all_user_text([]) is None


class TestNoneGuards:
    def test_extract_last_user_text_none_input(self):
        assert extract_last_user_text(None) is None

    def test_extract_model_text_none_input(self):
        assert extract_model_text(None) is None

    def test_extract_all_user_text_none_input(self):
        assert extract_all_user_text(None) is None
